import 'dart:convert';

/// 单帧记录。对应设备端回传的结构化文字总结（说明书 §4.1）。
///
/// 设计要点：
/// - `fromJson` 全字段容错：缺字段给默认值，类型不符做安全转换，绝不因脏数据崩溃。
/// - `highlight`（精彩度 0-1）缺失时兜底为 0.5，保证选片排序不空。
/// - `thumbPath` 为本地已下载的缩略图路径；`thumbUrl` 为设备局域网地址（阶段3拉图用）。
class Frame {
  /// 设备标识
  final String deviceId;

  /// 拍摄时间（ISO8601 字符串解析而来）
  final DateTime capturedAt;

  /// 全局唯一帧 ID（选片、去重、断点续传都靠它）
  final String imageId;

  /// 精彩度 / 记录价值 0-1，选片与排序核心
  final double highlight;

  /// 一句话场景描述（喂大模型做叙事的主要原料，也可直接当字幕）
  final String sceneSummary;

  /// 主题标签（主题聚类 / BGM 情绪匹配）
  final List<String> tags;

  /// 情绪基调
  final String mood;

  /// 设备局域网缩略图地址（阶段3 WiFi 拉图用）
  final String? thumbUrl;

  /// 原图是否可按需同步
  final bool origAvailable;

  /// 本地已下载的缩略图路径（阶段1 假数据直接指向 asset / 文件）
  final String? thumbPath;

  const Frame({
    required this.deviceId,
    required this.capturedAt,
    required this.imageId,
    required this.highlight,
    required this.sceneSummary,
    required this.tags,
    required this.mood,
    this.thumbUrl,
    this.origAvailable = false,
    this.thumbPath,
  });

  /// 所属日期（yyyy-MM-dd），用于按天聚合时间线
  String get day {
    final d = capturedAt;
    final m = d.month.toString().padLeft(2, '0');
    final day = d.day.toString().padLeft(2, '0');
    return '${d.year}-$m-$day';
  }

  Frame copyWith({
    String? thumbPath,
    String? thumbUrl,
    double? highlight,
    String? sceneSummary,
    List<String>? tags,
    String? mood,
  }) {
    return Frame(
      deviceId: deviceId,
      capturedAt: capturedAt,
      imageId: imageId,
      highlight: highlight ?? this.highlight,
      sceneSummary: sceneSummary ?? this.sceneSummary,
      tags: tags ?? this.tags,
      mood: mood ?? this.mood,
      thumbUrl: thumbUrl ?? this.thumbUrl,
      origAvailable: origAvailable,
      thumbPath: thumbPath ?? this.thumbPath,
    );
  }

  /// 容错解析：任何字段缺失/类型不符都不抛异常。
  factory Frame.fromJson(Map<String, dynamic> json) {
    return Frame(
      deviceId: _asString(json['device_id'], 'unknown'),
      capturedAt: _asDateTime(json['captured_at']),
      imageId: _asString(json['image_id'], _fallbackId()),
      highlight: _asDouble(json['highlight'], 0.5).clamp(0.0, 1.0),
      sceneSummary: _asString(json['scene_summary'], ''),
      tags: _asStringList(json['tags']),
      mood: _asString(json['mood'], ''),
      thumbUrl: json['thumb_url'] is String ? json['thumb_url'] as String : null,
      origAvailable: json['orig_available'] == true,
      thumbPath: json['thumb_path'] is String ? json['thumb_path'] as String : null,
    );
  }

  Map<String, dynamic> toJson() => {
        'device_id': deviceId,
        'captured_at': capturedAt.toIso8601String(),
        'image_id': imageId,
        'highlight': highlight,
        'scene_summary': sceneSummary,
        'tags': tags,
        'mood': mood,
        'thumb_url': thumbUrl,
        'orig_available': origAvailable,
        'thumb_path': thumbPath,
      };

  /// 数据库行（tags 存 JSON 字符串）
  Map<String, dynamic> toDbRow() => {
        'image_id': imageId,
        'device_id': deviceId,
        'captured_at': capturedAt.toIso8601String(),
        'day': day,
        'highlight': highlight,
        'scene_summary': sceneSummary,
        'tags': jsonEncode(tags),
        'mood': mood,
        'thumb_url': thumbUrl,
        'orig_available': origAvailable ? 1 : 0,
        'thumb_path': thumbPath,
      };

  factory Frame.fromDbRow(Map<String, dynamic> row) {
    return Frame(
      deviceId: _asString(row['device_id'], 'unknown'),
      capturedAt: _asDateTime(row['captured_at']),
      imageId: _asString(row['image_id'], _fallbackId()),
      highlight: _asDouble(row['highlight'], 0.5),
      sceneSummary: _asString(row['scene_summary'], ''),
      tags: _decodeTags(row['tags']),
      mood: _asString(row['mood'], ''),
      thumbUrl: row['thumb_url'] as String?,
      origAvailable: (row['orig_available'] ?? 0) == 1,
      thumbPath: row['thumb_path'] as String?,
    );
  }

  // ---- 容错工具 ----

  static String _asString(dynamic v, String fallback) {
    if (v is String && v.isNotEmpty) return v;
    if (v != null && v is! Map && v is! List) return v.toString();
    return fallback;
  }

  static double _asDouble(dynamic v, double fallback) {
    if (v is num) return v.toDouble();
    if (v is String) return double.tryParse(v) ?? fallback;
    return fallback;
  }

  static DateTime _asDateTime(dynamic v) {
    if (v is String) {
      final parsed = DateTime.tryParse(v);
      if (parsed != null) return parsed;
    }
    if (v is int) {
      // 兼容毫秒/秒级时间戳
      return DateTime.fromMillisecondsSinceEpoch(v > 1e12 ? v : v * 1000);
    }
    return DateTime.now();
  }

  static List<String> _asStringList(dynamic v) {
    if (v is List) {
      return v.map((e) => e.toString()).where((e) => e.isNotEmpty).toList();
    }
    if (v is String && v.isNotEmpty) {
      // 兼容逗号/顿号分隔
      return v.split(RegExp(r'[,，、]')).map((e) => e.trim()).where((e) => e.isNotEmpty).toList();
    }
    return const [];
  }

  static List<String> _decodeTags(dynamic v) {
    if (v is String && v.isNotEmpty) {
      try {
        final decoded = jsonDecode(v);
        return _asStringList(decoded);
      } catch (_) {
        return _asStringList(v);
      }
    }
    return const [];
  }

  static String _fallbackId() => 'frame_${DateTime.now().microsecondsSinceEpoch}';
}

import 'dart:convert';

/// 单个片段：一帧图片在 Vlog 里的呈现方式。
class Clip {
  /// 对应的帧 ID（关联到 Frame）
  final String imageId;

  /// 播放顺序（从 1 开始）
  final int order;

  /// 该帧的字幕（简短、口语、有情绪）
  final String caption;

  /// 停留时长（秒）
  final double durationSec;

  /// 与下一帧的转场：fade / slide / dissolve / none
  final String transition;

  const Clip({
    required this.imageId,
    required this.order,
    required this.caption,
    required this.durationSec,
    required this.transition,
  });

  factory Clip.fromJson(Map<String, dynamic> json) {
    return Clip(
      imageId: _str(json['image_id']),
      order: _int(json['order'], 0),
      caption: _str(json['caption']),
      durationSec: _double(json['duration_sec'], 2.5).clamp(0.8, 8.0),
      transition: _transition(json['transition']),
    );
  }

  Map<String, dynamic> toJson() => {
        'image_id': imageId,
        'order': order,
        'caption': caption,
        'duration_sec': durationSec,
        'transition': transition,
      };

  static const _allowedTransitions = {'fade', 'slide', 'dissolve', 'none'};

  static String _transition(dynamic v) {
    final s = (v is String) ? v.toLowerCase().trim() : '';
    return _allowedTransitions.contains(s) ? s : 'fade';
  }

  static String _str(dynamic v) => v == null ? '' : v.toString();

  static int _int(dynamic v, int fallback) {
    if (v is num) return v.toInt();
    if (v is String) return int.tryParse(v) ?? fallback;
    return fallback;
  }

  static double _double(dynamic v, double fallback) {
    if (v is num) return v.toDouble();
    if (v is String) return double.tryParse(v) ?? fallback;
    return fallback;
  }
}

/// Vlog 叙事脚本：大模型输出（或规则降级生成）的成片蓝图。
/// video_service 按这个脚本渲染 mp4。
class VlogScript {
  /// 成片标题
  final String title;

  /// 主题一句话
  final String theme;

  /// 片段列表（已按 order 排序）
  final List<Clip> clips;

  /// BGM 情绪（用于从内置 BGM 库匹配）
  final String bgmMood;

  /// 结尾语（片尾字幕）
  final String closing;

  /// 来源：llm（大模型）/ rule（规则降级）
  final String source;

  const VlogScript({
    required this.title,
    required this.theme,
    required this.clips,
    required this.bgmMood,
    required this.closing,
    this.source = 'llm',
  });

  factory VlogScript.fromJson(Map<String, dynamic> json, {String source = 'llm'}) {
    final rawClips = json['clips'];
    final clips = <Clip>[];
    if (rawClips is List) {
      for (final c in rawClips) {
        if (c is Map<String, dynamic>) {
          clips.add(Clip.fromJson(c));
        } else if (c is Map) {
          clips.add(Clip.fromJson(Map<String, dynamic>.from(c)));
        }
      }
    }
    clips.sort((a, b) => a.order.compareTo(b.order));
    return VlogScript(
      title: _str(json['title'], '我的一天'),
      theme: _str(json['theme'], ''),
      clips: clips,
      bgmMood: _str(json['bgm_mood'], '轻快'),
      closing: _str(json['closing'], ''),
      source: source,
    );
  }

  Map<String, dynamic> toJson() => {
        'title': title,
        'theme': theme,
        'clips': clips.map((c) => c.toJson()).toList(),
        'bgm_mood': bgmMood,
        'closing': closing,
        'source': source,
      };

  String toJsonString() => jsonEncode(toJson());

  factory VlogScript.fromJsonString(String s) {
    final decoded = jsonDecode(s);
    return VlogScript.fromJson(Map<String, dynamic>.from(decoded as Map),
        source: (decoded['source'] as String?) ?? 'llm');
  }

  static String _str(dynamic v, String fallback) {
    if (v is String && v.trim().isNotEmpty) return v.trim();
    return fallback;
  }
}

/// 大模型 API 配置（用户在设置页自己填）。
///
/// 安全约定：apiKey 不落普通存储/数据库/日志，单独走 flutter_secure_storage。
/// 这里的对象在内存中携带 apiKey 供调用；持久化时 key 与其余字段分开存。
class LlmConfig {
  /// OpenAI 兼容网关地址，App 会拼 /chat/completions
  final String baseUrl;

  /// 鉴权 key（Authorization: Bearer <key>）
  final String apiKey;

  /// 模型名（传给接口的 model 字段）
  final String model;

  /// 是否把缩略图也发给模型（多模态）。默认开，效果更好。
  final bool useImage;

  /// 单次请求超时（秒）
  final int timeoutSec;

  /// 响应最大 tokens
  final int maxTokens;

  const LlmConfig({
    this.baseUrl = '',
    this.apiKey = '',
    this.model = '',
    this.useImage = true,
    this.timeoutSec = 30,
    this.maxTokens = 3000,
  });

  /// 是否已配置到可用（三要素齐全）
  bool get isConfigured =>
      baseUrl.trim().isNotEmpty && apiKey.trim().isNotEmpty && model.trim().isNotEmpty;

  /// 拼接 chat/completions 完整地址
  String get chatCompletionsUrl {
    final base = baseUrl.trim().replaceAll(RegExp(r'/+$'), '');
    return '$base/chat/completions';
  }

  LlmConfig copyWith({
    String? baseUrl,
    String? apiKey,
    String? model,
    bool? useImage,
    int? timeoutSec,
    int? maxTokens,
  }) {
    return LlmConfig(
      baseUrl: baseUrl ?? this.baseUrl,
      apiKey: apiKey ?? this.apiKey,
      model: model ?? this.model,
      useImage: useImage ?? this.useImage,
      timeoutSec: timeoutSec ?? this.timeoutSec,
      maxTokens: maxTokens ?? this.maxTokens,
    );
  }

  /// 非敏感字段（存普通存储；apiKey 不在其中）
  Map<String, dynamic> toNonSecretJson() => {
        'base_url': baseUrl,
        'model': model,
        'use_image': useImage,
        'timeout_sec': timeoutSec,
        'max_tokens': maxTokens,
      };

  factory LlmConfig.fromNonSecretJson(Map<String, dynamic> json, {String apiKey = ''}) {
    return LlmConfig(
      baseUrl: (json['base_url'] as String?) ?? '',
      apiKey: apiKey,
      model: (json['model'] as String?) ?? '',
      useImage: json['use_image'] is bool ? json['use_image'] as bool : true,
      timeoutSec: (json['timeout_sec'] as num?)?.toInt() ?? 30,
      maxTokens: (json['max_tokens'] as num?)?.toInt() ?? 3000,
    );
  }
}

/// 大模型服务预设模板（设置页下拉，选后自动填 baseUrl）。
class LlmPreset {
  final String name;
  final String baseUrl;
  final String suggestedModel;

  const LlmPreset({
    required this.name,
    required this.baseUrl,
    this.suggestedModel = '',
  });

  static const List<LlmPreset> presets = [
    LlmPreset(
      name: '小米网关',
      baseUrl: 'https://api.llm.mioffice.cn/v1',
      suggestedModel: 'vertex_ai/gemini-2.5-flash-lite',
    ),
    LlmPreset(
      name: '自定义',
      baseUrl: '',
      suggestedModel: '',
    ),
  ];
}

import 'dart:convert';

import 'package:flutter_secure_storage/flutter_secure_storage.dart';

import '../models/llm_config.dart';

/// 大模型配置持久化。
///
/// 安全分层：
/// - apiKey 存 flutter_secure_storage（安卓 Keystore 加密），单独一个 key。
/// - 其余非敏感字段（baseUrl/model/useImage/timeout/maxTokens）以 JSON 存另一个 key。
/// 这样即使非敏感配置被导出/日志打印，也不会泄露 apiKey。
class ConfigStore {
  static const _kSecretApiKey = 'llm_api_key';
  static const _kNonSecret = 'llm_config_nonsecret';

  final FlutterSecureStorage _storage;

  ConfigStore({FlutterSecureStorage? storage})
      : _storage = storage ??
            const FlutterSecureStorage(
              aOptions: AndroidOptions(encryptedSharedPreferences: true),
            );

  /// 读取完整配置（含 apiKey）。未配置时返回默认空配置。
  Future<LlmConfig> load() async {
    final nonSecretRaw = await _storage.read(key: _kNonSecret);
    final apiKey = await _storage.read(key: _kSecretApiKey) ?? '';
    if (nonSecretRaw == null || nonSecretRaw.isEmpty) {
      return LlmConfig(apiKey: apiKey);
    }
    try {
      final map = jsonDecode(nonSecretRaw) as Map<String, dynamic>;
      return LlmConfig.fromNonSecretJson(map, apiKey: apiKey);
    } catch (_) {
      return LlmConfig(apiKey: apiKey);
    }
  }

  /// 保存配置：apiKey 与非敏感字段分开写。
  Future<void> save(LlmConfig config) async {
    await _storage.write(
      key: _kNonSecret,
      value: jsonEncode(config.toNonSecretJson()),
    );
    if (config.apiKey.trim().isEmpty) {
      await _storage.delete(key: _kSecretApiKey);
    } else {
      await _storage.write(key: _kSecretApiKey, value: config.apiKey.trim());
    }
  }

  /// 清空配置（含 key）
  Future<void> clear() async {
    await _storage.delete(key: _kSecretApiKey);
    await _storage.delete(key: _kNonSecret);
  }
}

import 'package:flutter_riverpod/flutter_riverpod.dart';

import '../models/llm_config.dart';
import '../services/config_store.dart';

/// ConfigStore 单例
final configStoreProvider = Provider<ConfigStore>((ref) => ConfigStore());

/// 大模型配置状态：加载 / 修改 / 保存。
class LlmConfigNotifier extends StateNotifier<LlmConfig> {
  final ConfigStore _store;

  LlmConfigNotifier(this._store) : super(const LlmConfig()) {
    _init();
  }

  bool _loaded = false;
  bool get loaded => _loaded;

  Future<void> _init() async {
    state = await _store.load();
    _loaded = true;
  }

  /// 重新从存储加载
  Future<void> reload() async {
    state = await _store.load();
    _loaded = true;
  }

  /// 更新内存中的配置（不落盘），供表单编辑时使用
  void update(LlmConfig config) {
    state = config;
  }

  /// 保存到持久化存储
  Future<void> save(LlmConfig config) async {
    await _store.save(config);
    state = config;
  }

  Future<void> clear() async {
    await _store.clear();
    state = const LlmConfig();
  }
}

final llmConfigProvider =
    StateNotifierProvider<LlmConfigNotifier, LlmConfig>((ref) {
  return LlmConfigNotifier(ref.watch(configStoreProvider));
});

import 'package:dio/dio.dart';

import '../models/llm_config.dart';

/// 测试连接结果
class LlmTestResult {
  final bool ok;
  final String message;
  const LlmTestResult(this.ok, this.message);
}

/// 大模型服务：调用户配置的 OpenAI 兼容 API。
///
/// 本文件当前包含"测试连接"能力；Vlog 脚本生成（generateScript）在任务 #4 补齐。
class LlmService {
  final Dio _dio;

  LlmService({Dio? dio}) : _dio = dio ?? Dio();

  /// 测试连接：发一个极小请求，验证 baseUrl/key/model 是否可用。
  /// 返回可读的成功/失败原因，供设置页即时反馈。
  Future<LlmTestResult> testConnection(LlmConfig config) async {
    if (!config.isConfigured) {
      return const LlmTestResult(false, '请先填写 Base URL、API Key 和模型名');
    }
    try {
      final resp = await _dio.post(
        config.chatCompletionsUrl,
        options: Options(
          headers: {
            'Authorization': 'Bearer ${config.apiKey.trim()}',
            'Content-Type': 'application/json',
          },
          sendTimeout: Duration(seconds: config.timeoutSec),
          receiveTimeout: Duration(seconds: config.timeoutSec),
          // 不自动抛异常，自己按状态码判断，给更友好的提示
          validateStatus: (_) => true,
        ),
        data: {
          'model': config.model.trim(),
          'max_tokens': 16,
          'messages': [
            {'role': 'user', 'content': '回复一个字：好'},
          ],
        },
      );

      final code = resp.statusCode ?? 0;
      if (code == 200) {
        return const LlmTestResult(true, '连接成功，模型可用');
      }
      return LlmTestResult(false, _describeHttp(code, resp.data));
    } on DioException catch (e) {
      return LlmTestResult(false, _describeDioError(e));
    } catch (e) {
      return LlmTestResult(false, '未知错误：$e');
    }
  }

  String _describeHttp(int code, dynamic body) {
    switch (code) {
      case 401:
        return '鉴权失败（401）：API Key 可能不对';
      case 403:
        return '无权限（403）：Key 无该模型权限';
      case 404:
        return '地址或模型不存在（404）：检查 Base URL / 模型名';
      case 429:
        return '请求过于频繁（429）：稍后再试';
      default:
        final snippet = body?.toString() ?? '';
        final short = snippet.length > 120 ? snippet.substring(0, 120) : snippet;
        return 'HTTP $code：$short';
    }
  }

  String _describeDioError(DioException e) {
    switch (e.type) {
      case DioExceptionType.connectionTimeout:
      case DioExceptionType.sendTimeout:
      case DioExceptionType.receiveTimeout:
        return '连接超时：检查网络或调大超时时间';
      case DioExceptionType.connectionError:
        return '连不上服务器：检查 Base URL 和网络';
      case DioExceptionType.badCertificate:
        return '证书错误：HTTPS 证书校验失败';
      default:
        return '请求失败：${e.message ?? e.type.name}';
    }
  }
}

/// LlmService 单例入口（provider 在 providers 层引用）
final _sharedLlmService = LlmService();
LlmService get sharedLlmService => _sharedLlmService;

import 'package:flutter/material.dart';
