/// 设置页 —— 核心是"用户自配大模型 API"。
///
/// 功能：预设模板下拉（选后自动填 Base URL）、Base URL / API Key / 模型名 输入、
/// 多模态开关（默认开）、超时/最大tokens、测试连接（即时反馈）、保存。
class SettingsPage extends ConsumerStatefulWidget {
  const SettingsPage({super.key});

  @override
  ConsumerState<SettingsPage> createState() => _SettingsPageState();
}

class _SettingsPageState extends ConsumerState<SettingsPage> {
  final _baseUrlCtrl = TextEditingController();
  final _apiKeyCtrl = TextEditingController();
  final _modelCtrl = TextEditingController();
  final _timeoutCtrl = TextEditingController(text: '30');
  final _maxTokensCtrl = TextEditingController(text: '3000');

  bool _useImage = true;
  bool _obscureKey = true;
  bool _testing = false;
  bool _syncedFromState = false;
  String _presetName = '自定义';

  @override
  void dispose() {
    _baseUrlCtrl.dispose();
    _apiKeyCtrl.dispose();
    _modelCtrl.dispose();
    _timeoutCtrl.dispose();
    _maxTokensCtrl.dispose();
    super.dispose();
  }

  /// 首次拿到已保存配置时，把它填进表单
  void _syncFromState(LlmConfig cfg) {
    if (_syncedFromState) return;
    _syncedFromState = true;
    _baseUrlCtrl.text = cfg.baseUrl;
    _apiKeyCtrl.text = cfg.apiKey;
    _modelCtrl.text = cfg.model;
    _timeoutCtrl.text = cfg.timeoutSec.toString();
    _maxTokensCtrl.text = cfg.maxTokens.toString();
    _useImage = cfg.useImage;
    // 匹配预设名
    for (final p in LlmPreset.presets) {
      if (p.baseUrl.isNotEmpty && p.baseUrl == cfg.baseUrl) {
        _presetName = p.name;
        break;
      }
    }
  }

  LlmConfig _buildConfig() {
    return LlmConfig(
      baseUrl: _baseUrlCtrl.text.trim(),
      apiKey: _apiKeyCtrl.text.trim(),
      model: _modelCtrl.text.trim(),
      useImage: _useImage,
      timeoutSec: int.tryParse(_timeoutCtrl.text.trim()) ?? 30,
      maxTokens: int.tryParse(_maxTokensCtrl.text.trim()) ?? 3000,
    );
  }

  void _applyPreset(String name) {
