import 'dart:convert';
import 'dart:io';
import 'dart:math';

import 'package:dio/dio.dart';
import 'package:flutter/services.dart' show rootBundle;

import '../models/frame.dart';
import '../models/llm_config.dart';
import '../models/vlog_script.dart';

/// 测试连接结果
class LlmTestResult {
  final bool ok;
  final String message;
  const LlmTestResult(this.ok, this.message);
}

/// 脚本生成结果：脚本 + 来源标记 + 出错原因（若降级）。
class ScriptResult {
  final VlogScript script;

  /// llm=大模型生成；rule=规则降级
  final String source;

  /// 降级时的原因（成功为 null）
  final String? fallbackReason;

  const ScriptResult(this.script, this.source, {this.fallbackReason});
}

// ============ Vlog 脚本生成 ============

/// 导演角色的 System Prompt：让模型只输出结构化 JSON 脚本。
static const String _directorPrompt =
    '你是资深短视频剪辑与叙事导演。用户会给你一天中若干张画面，每张附有：'
    '编号(image_id)、拍摄时间、精彩度(highlight 0-1)、一句话场景描述(scene_summary)、'
    '标签(tags)、情绪(mood)；可能还附有对应的缩略图。\n'
    '你的任务：从这些画面里挑选并编排出一段有主题、有起承转合的 Vlog。要求：\n'
    '1. 依据精彩度和叙事需要选片（不必全用，也可调整先后，但顺序要符合时间与情绪流动）；\n'
    '2. 为每个选中的画面写一句简短、口语、有情绪的字幕(caption)，不要复述场景描述原文；\n'
    '3. 给每个画面一个停留时长 duration_sec（1.5~4 秒），并指定与下一张的转场'
    '(transition: fade/slide/dissolve/none)；\n'
    '4. 给整段一个有记忆点的标题(title)、一句主题(theme)、一个 BGM 情绪(bgm_mood，如"轻快明亮""温柔怀旧")、'
    '一句片尾语(closing)；\n'
    '5. 严格只输出 JSON，不要任何解释或 markdown 包裹，格式：\n'
    '{"title":"...","theme":"...","clips":[{"image_id":"...","order":1,"caption":"...",'
    '"duration_sec":2.5,"transition":"fade"}],"bgm_mood":"...","closing":"..."}';

/// 生成 Vlog 脚本。
/// - config 未配置 / 请求失败 / 解析失败 → 自动规则降级（永不失败）。
/// - config.useImage 且帧有本地缩略图时，走多模态把图一起发。
Future<ScriptResult> generateScript(LlmConfig config, List<Frame> frames) async {
  if (frames.isEmpty) {
    return ScriptResult(buildFallbackScript(frames), 'rule',
        fallbackReason: '无可用画面');
  }
  if (!config.isConfigured) {
    return ScriptResult(buildFallbackScript(frames), 'rule',
        fallbackReason: '未配置大模型');
  }

  try {
    final userContent = await _buildUserContent(config, frames);
    final resp = await _dio.post(
      config.chatCompletionsUrl,
      options: Options(
        headers: {
          'Authorization': 'Bearer ${config.apiKey.trim()}',
          'Content-Type': 'application/json',
        },
        sendTimeout: Duration(seconds: config.timeoutSec),
        receiveTimeout: Duration(seconds: config.timeoutSec),
        validateStatus: (_) => true,
      ),
      data: {
        'model': config.model.trim(),
        'max_tokens': config.maxTokens,
        'messages': [
          {'role': 'system', 'content': _directorPrompt},
          {'role': 'user', 'content': userContent},
        ],
      },
    );

    if (resp.statusCode != 200) {
      return ScriptResult(buildFallbackScript(frames), 'rule',
          fallbackReason: _describeHttp(resp.statusCode ?? 0, resp.data));
    }

    final content = _extractContent(resp.data);
    final parsed = _parseScriptJson(content, frames);
    if (parsed != null) {
      return ScriptResult(parsed, 'llm');
    }
    return ScriptResult(buildFallbackScript(frames), 'rule',
        fallbackReason: '模型输出无法解析');
  } on DioException catch (e) {
    return ScriptResult(buildFallbackScript(frames), 'rule',
        fallbackReason: _describeDioError(e));
  } catch (e) {
    return ScriptResult(buildFallbackScript(frames), 'rule',
        fallbackReason: '异常：$e');
  }
}

/// 构造 user 消息内容。多模态时为 content 数组（文本 + 若干 image_url）。
Future<dynamic> _buildUserContent(LlmConfig config, List<Frame> frames) async {
  final text = _buildFramesText(frames);
  if (!config.useImage) {
    return text;
  }
  final parts = <Map<String, dynamic>>[
    {'type': 'text', 'text': text},
  ];
  for (final f in frames) {
    final dataUrl = await _imageToDataUrl(f.thumbPath);
    if (dataUrl != null) {
      parts.add({
        'type': 'text',
        'text': '↑下面这张图对应 image_id=${f.imageId}',
      });
      parts.add({
        'type': 'image_url',
        'image_url': {'url': dataUrl},
      });
    }
  }
  // 若没有任何图片可发，退回纯文本
  if (parts.length == 1) return text;
  return parts;
}

/// 把当天帧组织成给模型的文字清单。
String _buildFramesText(List<Frame> frames) {
  final sorted = [...frames]..sort((a, b) => a.capturedAt.compareTo(b.capturedAt));
  final sb = StringBuffer();
  sb.writeln('这是我今天记录的 ${sorted.length} 个画面，请编排成一段 Vlog：');
  for (final f in sorted) {
    final t = f.capturedAt;
    final hh = t.hour.toString().padLeft(2, '0');
    final mm = t.minute.toString().padLeft(2, '0');
    sb.writeln(
      '- image_id=${f.imageId} | 时间 $hh:$mm | 精彩度 ${f.highlight.toStringAsFixed(2)} '
      '| 情绪 ${f.mood.isEmpty ? "未知" : f.mood} '
      '| 标签 ${f.tags.isEmpty ? "无" : f.tags.join("/")} '
      '| 场景 ${f.sceneSummary.isEmpty ? "无描述" : f.sceneSummary}',
    );
  }
  return sb.toString();
}

/// 读取本地缩略图转 data URL。支持 asset 路径（assets/ 开头）与文件路径。失败返回 null。
Future<String?> _imageToDataUrl(String? thumbPath) async {
  if (thumbPath == null || thumbPath.isEmpty) return null;
  try {
    List<int> bytes;
    if (thumbPath.startsWith('assets/')) {
      final data = await rootBundle.load(thumbPath);
      bytes = data.buffer.asUint8List();
    } else {
      final file = File(thumbPath);
      if (!await file.exists()) return null;
      bytes = await file.readAsBytes();
    }
    final b64 = base64Encode(bytes);
    return 'data:image/jpeg;base64,$b64';
  } catch (_) {
    return null;
  }
}

/// 从 OpenAI 兼容响应里取出 content 文本（兼容思考型模型的 reasoning_content）。
String? _extractContent(dynamic data) {
  try {
    final choices = data['choices'];
    if (choices is List && choices.isNotEmpty) {
      final msg = choices[0]['message'];
      if (msg is Map) {
        final c = msg['content'];
        if (c is String && c.trim().isNotEmpty) return c;
        final rc = msg['reasoning_content'];
        if (rc is String && rc.trim().isNotEmpty) return rc;
      }
    }
  } catch (_) {}
  return null;
}

/// 严格解析模型输出的脚本 JSON：去 ```json``` 包裹、取首尾大括号、过滤非法 image_id。
VlogScript? _parseScriptJson(String? content, List<Frame> frames) {
  if (content == null) return null;
  var s = content.trim();
  if (s.startsWith('```')) {
    s = s.replaceAll(RegExp(r'^```[a-zA-Z]*'), '').replaceAll(RegExp(r'```$'), '').trim();
  }
  final l = s.indexOf('{');
  final r = s.lastIndexOf('}');
  if (l == -1 || r == -1 || r <= l) return null;
  Map<String, dynamic> obj;
  try {
    obj = Map<String, dynamic>.from(jsonDecode(s.substring(l, r + 1)) as Map);
  } catch (_) {
    return null;
  }
  final script = VlogScript.fromJson(obj, source: 'llm');
  // 过滤掉不在帧集合里的 image_id，避免渲染时找不到图
  final validIds = frames.map((f) => f.imageId).toSet();
  final validClips = script.clips.where((c) => validIds.contains(c.imageId)).toList();
  if (validClips.isEmpty) return null;
  // 重新规整 order
  for (var i = 0; i < validClips.length; i++) {
    validClips[i] = Clip(
      imageId: validClips[i].imageId,
      order: i + 1,
      caption: validClips[i].caption,
      durationSec: validClips[i].durationSec,
      transition: validClips[i].transition,
    );
  }
  return VlogScript(
    title: script.title,
    theme: script.theme,
    clips: validClips,
    bgmMood: script.bgmMood,
    closing: script.closing,
    source: 'llm',
  );
}

/// 规则降级脚本：按精彩度选前 N 帧 → 按时间排序 → 场景描述当字幕。永不失败。
VlogScript buildFallbackScript(List<Frame> frames) {
  if (frames.isEmpty) {
    return const VlogScript(
      title: '空空如也的一天',
      theme: '',
      clips: [],
      bgmMood: '安静',
      closing: '明天再出发。',
      source: 'rule',
    );
  }
  // 按精彩度降序取前 N（最多 12 帧），再按时间排序保证叙事顺
  final byHighlight = [...frames]..sort((a, b) => b.highlight.compareTo(a.highlight));
  final picked = byHighlight.take(min(12, byHighlight.length)).toList()
    ..sort((a, b) => a.capturedAt.compareTo(b.capturedAt));

  final clips = <Clip>[];
  for (var i = 0; i < picked.length; i++) {
    final f = picked[i];
    clips.add(Clip(
      imageId: f.imageId,
      order: i + 1,
      caption: f.sceneSummary.isNotEmpty ? f.sceneSummary : _timeLabel(f.capturedAt),
      durationSec: 2.5,
      transition: 'fade',
    ));
  }

  final day = picked.first.capturedAt;
  final title = '${day.year}年${day.month}月${day.day}日 · 我的一天';
  final mood = _dominantMood(picked);

  return VlogScript(
    title: title,
    theme: _dominantTags(picked),
    clips: clips,
    bgmMood: mood,
    closing: '又收集了一天的光。',
    source: 'rule',
  );
}

String _timeLabel(DateTime t) {
  final hh = t.hour.toString().padLeft(2, '0');
  final mm = t.minute.toString().padLeft(2, '0');
  return '$hh:$mm';
}

/// 取出现最多的情绪作为 BGM 情绪
String _dominantMood(List<Frame> frames) {
  final count = <String, int>{};
  for (final f in frames) {
    if (f.mood.isNotEmpty) count[f.mood] = (count[f.mood] ?? 0) + 1;
  }
  if (count.isEmpty) return '轻快';
  return count.entries.reduce((a, b) => a.value >= b.value ? a : b).key;
}

/// 取出现最多的标签作为主题
String _dominantTags(List<Frame> frames) {
  final count = <String, int>{};
  for (final f in frames) {
    for (final t in f.tags) {
      count[t] = (count[t] ?? 0) + 1;
    }
  }
  if (count.isEmpty) return '生活碎片';
  final sorted = count.entries.toList()..sort((a, b) => b.value.compareTo(a.value));
  return sorted.take(3).map((e) => e.key).join('·');
}

