import 'dart:async';
import 'dart:io';

import 'package:flutter/services.dart' show rootBundle;
import 'package:path/path.dart' as p;
import 'package:path_provider/path_provider.dart';

import 'package:ffmpeg_kit_flutter_new/ffmpeg_kit.dart';
import 'package:ffmpeg_kit_flutter_new/ffmpeg_kit_config.dart';
import 'package:ffmpeg_kit_flutter_new/return_code.dart';

import '../models/frame.dart';
import '../models/vlog_script.dart';

/// 视频合成进度回调（0.0 ~ 1.0）+ 阶段文字
typedef RenderProgress = void Function(double progress, String stage);

/// 渲染结果
class RenderResult {
  final bool ok;
  final String? outputPath;
  final String? error;
  const RenderResult({required this.ok, this.outputPath, this.error});
}

/// 本地视频合成服务（技术核心）。
///
/// 策略（分步、可靠、易排错）：
/// 1) 逐帧：把每张图渲染成一段带 Ken Burns 动效 + 中文字幕的竖屏片段 mp4。
/// 2) 拼接：用 concat 把所有片段顺序连接。
/// 3) 配乐：叠加 BGM（按脚本 bgm_mood 从内置库匹配），按视频时长裁剪 + 淡出。
///
/// 竖屏输出 1080x1920，H.264 + AAC。字幕用 assets/fonts 里的中文字体，避免乱码。
class VideoService {
  static const int outW = 1080;
  static const int outH = 1920;
  static const int fps = 30;

  /// 主入口：按脚本渲染成片，返回 mp4 路径。
  ///
  /// frames：脚本引用到的帧（需含本地可读的 thumbPath，asset 或文件均可）。
  Future<RenderResult> render({
    required VlogScript script,
    required List<Frame> frames,
    RenderProgress? onProgress,
  }) async {
    if (script.clips.isEmpty) {
      return const RenderResult(ok: false, error: '脚本没有可渲染的片段');
    }

    final frameMap = {for (final f in frames) f.imageId: f};
    final workDir = await _prepareWorkDir();

    try {
      // 字体文件（中文字幕）
      final fontPath = await _prepareAsset('assets/fonts/subtitle.ttf', workDir, 'subtitle.ttf');

      // ---- 1) 逐帧渲染片段 ----
      final segmentPaths = <String>[];
      double totalDuration = 0;
      for (var i = 0; i < script.clips.length; i++) {
        final clip = script.clips[i];
        final frame = frameMap[clip.imageId];
        if (frame == null || frame.thumbPath == null) continue;

        onProgress?.call(
          i / script.clips.length * 0.7,
          '渲染第 ${i + 1}/${script.clips.length} 个画面',
        );

        final imgPath = await _materializeImage(frame.thumbPath!, workDir, i);
        if (imgPath == null) continue;

        final segPath = p.join(workDir, 'seg_$i.mp4');
        final ok = await _renderSegment(
          imagePath: imgPath,
          outputPath: segPath,
          caption: clip.caption,
          durationSec: clip.durationSec,
          fontPath: fontPath,
          kenBurnsIn: i.isEven, // 交替放大/缩小，画面更有节奏
        );
        if (ok) {
          segmentPaths.add(segPath);
          totalDuration += clip.durationSec;
        }
      }

      if (segmentPaths.isEmpty) {
        return const RenderResult(ok: false, error: '没有成功渲染的片段（检查图片路径）');
      }

      // ---- 2) 拼接片段 ----
      onProgress?.call(0.78, '拼接片段');
      final concatVideo = p.join(workDir, 'concat.mp4');
      final concatOk = await _concatSegments(segmentPaths, concatVideo, workDir);
      if (!concatOk) {
        return const RenderResult(ok: false, error: '片段拼接失败');
      }

      // ---- 3) 叠加 BGM ----
      onProgress?.call(0.88, '合成配乐');
      final bgmPath = await _prepareBgm(script.bgmMood, workDir);
      final outputPath = await _finalOutputPath();
      final finalOk = await _muxBgm(
        videoPath: concatVideo,
        bgmPath: bgmPath,
        outputPath: outputPath,
        videoDuration: totalDuration,
      );

      onProgress?.call(1.0, '完成');
      if (!finalOk) {
        // BGM 失败也不至于前功尽弃：把无声成片直接作为输出
        final fallback = await _finalOutputPath();
        await File(concatVideo).copy(fallback);
        return RenderResult(ok: true, outputPath: fallback);
      }
      return RenderResult(ok: true, outputPath: outputPath);
    } catch (e) {
      return RenderResult(ok: false, error: '渲染异常：$e');
    }
  }

  // ---- 单帧片段：Ken Burns + 字幕 ----
  Future<bool> _renderSegment({
    required String imagePath,
    required String outputPath,
    required String caption,
    required double durationSec,
    required String? fontPath,
    required bool kenBurnsIn,
  }) async {
    final frameCount = (durationSec * fps).round().clamp(1, 100000);

    // 先把图缩放并居中裁剪/铺满到竖屏画布，再做 zoompan 缓慢缩放（Ken Burns）
    // scale 先放大到覆盖画布，避免 zoompan 边缘露黑边
    final zoomExpr = kenBurnsIn
        ? "zoom='min(zoom+0.0008,1.15)'"
        : "zoom='if(eq(on,0),1.15,max(zoom-0.0008,1.0))'";

    final filters = <String>[
      // 缩放铺满竖屏并裁剪
      "scale=$outW:$outH:force_original_aspect_ratio=increase,crop=$outW:$outH",
      // Ken Burns
      "zoompan=$zoomExpr:d=$frameCount:s=${outW}x$outH:fps=$fps",
      "setsar=1",
    ];

    // 字幕（底部，半透明黑底描边，中文字体）
    if (caption.trim().isNotEmpty) {
      final safe = _escapeDrawText(caption.trim());
      final fontClause = (fontPath != null) ? "fontfile='${_escapePath(fontPath)}':" : '';
      filters.add(
        "drawtext=${fontClause}text='$safe':fontcolor=white:fontsize=52:"
        "box=1:boxcolor=black@0.45:boxborderw=18:"
        "x=(w-text_w)/2:y=h-text_h-160:line_spacing=8",
      );
    }

    final args = <String>[
      '-y',
      '-loop', '1',
      '-i', imagePath,
      '-t', durationSec.toStringAsFixed(2),
      '-vf', filters.join(','),
      '-r', '$fps',
      '-c:v', 'libx264',
      '-pix_fmt', 'yuv420p',
      '-preset', 'ultrafast',
      outputPath,
    ];

    return _run(args);
  }

  // ---- 拼接：concat demuxer ----
  Future<bool> _concatSegments(List<String> segments, String output, String workDir) async {
    final listFile = File(p.join(workDir, 'concat_list.txt'));
    final sb = StringBuffer();
    for (final s in segments) {
      // concat demuxer 要求路径转义单引号
      sb.writeln("file '${s.replaceAll("'", r"'\''")}'");
    }
    await listFile.writeAsString(sb.toString());

    final args = <String>[
      '-y',
      '-f', 'concat',
      '-safe', '0',
      '-i', listFile.path,
      '-c', 'copy',
      output,
    ];
    // 片段编码参数一致，可直接 copy；若 copy 失败则重新编码
    final ok = await _run(args);
    if (ok) return true;
    return _run([
      '-y', '-f', 'concat', '-safe', '0', '-i', listFile.path,
      '-c:v', 'libx264', '-pix_fmt', 'yuv420p', '-preset', 'ultrafast', output,
    ]);
  }

  // ---- 混入 BGM ----
  Future<bool> _muxBgm({
    required String videoPath,
    required String? bgmPath,
    required String outputPath,
    required double videoDuration,
  }) async {
    if (bgmPath == null) {
      // 无 BGM：直接封装（复制视频流，无音轨）
      return _run(['-y', '-i', videoPath, '-c', 'copy', outputPath]);
    }
    final fadeStart = (videoDuration - 2).clamp(0, videoDuration).toStringAsFixed(2);
    final args = <String>[
      '-y',
      '-i', videoPath,
      '-i', bgmPath,
      '-filter_complex',
      '[1:a]afade=t=out:st=$fadeStart:d=2[a]',
      '-map', '0:v',
      '-map', '[a]',
      '-c:v', 'copy',
      '-c:a', 'aac',
      '-shortest',
      outputPath,
    ];
    return _run(args);
  }

  // ---- 执行 FFmpeg（参数数组，异步 + 返回码判断） ----
  Future<bool> _run(List<String> args) async {
    final completer = Completer<bool>();
    await FFmpegKit.executeWithArgumentsAsync(
      args,
      (session) async {
        final rc = await session.getReturnCode();
        completer.complete(ReturnCode.isSuccess(rc));
      },
    );
    return completer.future;
  }

  // ---- 资源准备 ----

  Future<String> _prepareWorkDir() async {
    final tmp = await getTemporaryDirectory();
    final dir = Directory(p.join(tmp.path, 'vlog_work_${DateTime.now().millisecondsSinceEpoch}'));
    if (await dir.exists()) await dir.delete(recursive: true);
    await dir.create(recursive: true);
    return dir.path;
  }

  Future<String> _finalOutputPath() async {
    final docs = await getApplicationDocumentsDirectory();
    final outDir = Directory(p.join(docs.path, 'vlogs'));
    if (!await outDir.exists()) await outDir.create(recursive: true);
    return p.join(outDir.path, 'vlog_${DateTime.now().millisecondsSinceEpoch}.mp4');
  }

  /// 把帧的缩略图落成 work 目录里的真实文件（asset 需先释放）。
  Future<String?> _materializeImage(String thumbPath, String workDir, int idx) async {
    try {
      if (thumbPath.startsWith('assets/')) {
        return _prepareAsset(thumbPath, workDir, 'img_$idx.jpg');
      }
      final f = File(thumbPath);
      if (await f.exists()) return thumbPath;
      return null;
    } catch (_) {
      return null;
    }
  }

  /// 从 assets 释放文件到工作目录。失败返回 null。
  Future<String?> _prepareAsset(String assetPath, String workDir, String fileName) async {
    try {
      final data = await rootBundle.load(assetPath);
      final file = File(p.join(workDir, fileName));
      await file.writeAsBytes(data.buffer.asUint8List());
      return file.path;
    } catch (_) {
      return null;
    }
  }

  /// 按情绪匹配内置 BGM；找不到返回 null（无声成片）。
  Future<String?> _prepareBgm(String mood, String workDir) async {
    // 内置 BGM 文件名约定：assets/bgm/<key>.mp3
    // 简单情绪→文件映射；实际文件在任务#7放入。
    final key = _matchBgmKey(mood);
    final asset = 'assets/bgm/$key.mp3';
    return _prepareAsset(asset, workDir, 'bgm.mp3');
  }

  String _matchBgmKey(String mood) {
    final m = mood;
    if (m.contains('快') || m.contains('明') || m.contains('活')) return 'upbeat';
    if (m.contains('柔') || m.contains('怀') || m.contains('暖') || m.contains('静') || m.contains('宁')) {
      return 'gentle';
    }
    if (m.contains('燃') || m.contains('激') || m.contains('励')) return 'epic';
    return 'gentle'; // 默认
  }

  /// drawtext 文本转义：处理特殊字符，避免 FFmpeg 解析错误。
  String _escapeDrawText(String text) {
    return text
        .replaceAll('\\', r'\\')
        .replaceAll(':', r'\:')
        .replaceAll("'", r'\’') // 单引号换成中文引号，规避 filtergraph 解析
        .replaceAll('%', r'\%')
        .replaceAll('\n', ' ');
  }

  String _escapePath(String path) {
    // Windows 反斜杠与冒号在 filtergraph 中需转义；Android 为正斜杠一般无碍。
    return path.replaceAll('\\', '/').replaceAll(':', r'\:');
  }

  /// 取消当前所有 FFmpeg 会话
  Future<void> cancel() async {
    await FFmpegKitConfig.init();
    await FFmpegKit.cancel();
  }
}

