import 'dart:convert';

import 'package:flutter/services.dart' show rootBundle;
import 'package:flutter_riverpod/flutter_riverpod.dart';

import '../models/frame.dart';

/// 帧数据源。
///
/// 阶段1：从 assets/mock/frames.json 读假数据（每帧的 thumb_path 指向 assets/mock/images/*）。
/// 阶段3：改为从本地数据库（设备同步后写入）读取。接口保持不变，替换实现即可。
class FramesRepository {
  /// 加载全部帧（按时间倒序）
  Future<List<Frame>> loadAll() async {
    try {
      final raw = await rootBundle.loadString('assets/mock/frames.json');
      final decoded = jsonDecode(raw);
      final list = <Frame>[];
      if (decoded is List) {
        for (final e in decoded) {
          if (e is Map) {
            list.add(Frame.fromJson(Map<String, dynamic>.from(e)));
          }
        }
      }
      list.sort((a, b) => b.capturedAt.compareTo(a.capturedAt));
      return list;
    } catch (_) {
      return [];
    }
  }
}

final framesRepositoryProvider = Provider<FramesRepository>((ref) => FramesRepository());

/// 全部帧（异步加载）
final framesProvider = FutureProvider<List<Frame>>((ref) async {
  return ref.watch(framesRepositoryProvider).loadAll();
});

/// 按天分组的帧：{ 'yyyy-MM-dd': [Frame...] }，天按倒序，天内按时间正序。
final framesByDayProvider = FutureProvider<Map<String, List<Frame>>>((ref) async {
  final frames = await ref.watch(framesProvider.future);
  final map = <String, List<Frame>>{};
  for (final f in frames) {
    map.putIfAbsent(f.day, () => []).add(f);
  }
  for (final entry in map.entries) {
    entry.value.sort((a, b) => a.capturedAt.compareTo(b.capturedAt));
  }
  // 按天倒序返回
  final sortedKeys = map.keys.toList()..sort((a, b) => b.compareTo(a));
  return {for (final k in sortedKeys) k: map[k]!};
});

import 'package:flutter_riverpod/flutter_riverpod.dart';

import '../models/frame.dart';
import '../models/vlog_script.dart';
import '../services/llm_service.dart';
import '../services/video_service.dart';
import 'llm_config_provider.dart';

/// 生成阶段
enum GenStage { idle, scripting, rendering, done, error }

/// 生成状态
class GenerationState {
  final GenStage stage;

  /// 当前阶段进度 0-1
  final double progress;

  /// 阶段/提示文字
  final String message;

  /// 生成出的脚本（脚本完成后可用）
  final VlogScript? script;

  /// 脚本来源：llm / rule
  final String? scriptSource;

  /// 成片路径（完成后可用）
  final String? videoPath;

  /// 错误信息
  final String? error;

  const GenerationState({
    this.stage = GenStage.idle,
    this.progress = 0,
    this.message = '',
    this.script,
    this.scriptSource,
    this.videoPath,
    this.error,
  });

  GenerationState copyWith({
    GenStage? stage,
    double? progress,
    String? message,
    VlogScript? script,
    String? scriptSource,
    String? videoPath,
    String? error,
  }) {
    return GenerationState(
      stage: stage ?? this.stage,
      progress: progress ?? this.progress,
      message: message ?? this.message,
      script: script ?? this.script,
      scriptSource: scriptSource ?? this.scriptSource,
      videoPath: videoPath ?? this.videoPath,
      error: error ?? this.error,
    );
  }

  bool get isBusy => stage == GenStage.scripting || stage == GenStage.rendering;
}

class GenerationNotifier extends StateNotifier<GenerationState> {
  final Ref _ref;
  final LlmService _llm;
  final VideoService _video;

  GenerationNotifier(this._ref, {LlmService? llm, VideoService? video})
      : _llm = llm ?? sharedLlmService,
        _video = video ?? VideoService(),
        super(const GenerationState());

  /// 一键生成：脚本 → 渲染。
  Future<void> generate(List<Frame> frames) async {
    if (frames.isEmpty) {
      state = const GenerationState(stage: GenStage.error, error: '这一天没有可用画面');
      return;
    }

    // 1) 脚本生成
    state = const GenerationState(
      stage: GenStage.scripting,
      progress: 0.2,
      message: '正在编排叙事脚本…',
    );
    final config = _ref.read(llmConfigProvider);
    final scriptResult = await _llm.generateScript(config, frames);

    state = state.copyWith(
      stage: GenStage.rendering,
      progress: 0.0,
      message: scriptResult.source == 'llm' ? '脚本就绪，开始渲染…' : '（本地脚本）开始渲染…',
      script: scriptResult.script,
      scriptSource: scriptResult.source,
    );

    // 2) 视频渲染
    final result = await _video.render(
      script: scriptResult.script,
      frames: frames,
      onProgress: (prog, stage) {
        state = state.copyWith(
          stage: GenStage.rendering,
          progress: prog,
          message: stage,
        );
      },
    );

    if (result.ok && result.outputPath != null) {
      state = state.copyWith(
        stage: GenStage.done,
        progress: 1.0,
        message: '生成完成',
        videoPath: result.outputPath,
      );
    } else {
      state = state.copyWith(
        stage: GenStage.error,
        message: '渲染失败',
        error: result.error ?? '未知错误',
      );
    }
  }

  /// 用已有脚本重新渲染（审片编辑后用，阶段2）
  Future<void> reRender(VlogScript script, List<Frame> frames) async {
    state = state.copyWith(
      stage: GenStage.rendering,
      progress: 0,
      message: '重新渲染…',
      script: script,
    );
    final result = await _video.render(
      script: script,
      frames: frames,
      onProgress: (prog, stage) {
        state = state.copyWith(stage: GenStage.rendering, progress: prog, message: stage);
      },
    );
    if (result.ok && result.outputPath != null) {
      state = state.copyWith(
        stage: GenStage.done,
        progress: 1.0,
        message: '生成完成',
        videoPath: result.outputPath,
      );
    } else {
      state = state.copyWith(stage: GenStage.error, error: result.error ?? '未知错误');
    }
  }

  void reset() => state = const GenerationState();
}

final generationProvider =
    StateNotifierProvider<GenerationNotifier, GenerationState>((ref) {
  return GenerationNotifier(ref);
});

import 'dart:io';

import 'package:flutter/material.dart';

/// 统一的帧缩略图显示：自动区分 asset 路径与文件路径。
class FrameThumb extends StatelessWidget {
  final String? path;
  final double? width;
  final double? height;
  final BoxFit fit;
  final BorderRadius? radius;

  const FrameThumb({
    super.key,
    required this.path,
    this.width,
    this.height,
    this.fit = BoxFit.cover,
    this.radius,
  });

  @override
  Widget build(BuildContext context) {
    Widget img;
    if (path == null || path!.isEmpty) {
      img = _placeholder();
    } else if (path!.startsWith('assets/')) {
      img = Image.asset(path!, width: width, height: height, fit: fit,
          errorBuilder: (_, __, ___) => _placeholder());
    } else {
      img = Image.file(File(path!), width: width, height: height, fit: fit,
          errorBuilder: (_, __, ___) => _placeholder());
    }
    if (radius != null) {
      return ClipRRect(borderRadius: radius!, child: img);
    }
    return img;
  }

  Widget _placeholder() {
    return Container(
      width: width,
      height: height,
      color: Colors.grey.shade300,
      child: const Icon(Icons.image_not_supported_outlined, color: Colors.grey),
    );
  }
}

import 'dart:io';

import 'package:flutter/material.dart';
import 'package:gal/gal.dart';
import 'package:video_player/video_player.dart';

/// 成片播放页：播放 mp4 + 保存到相册。
class PlayerPage extends StatefulWidget {
  final String videoPath;
  final String title;

  const PlayerPage({super.key, required this.videoPath, this.title = '我的 Vlog'});

  @override
  State<PlayerPage> createState() => _PlayerPageState();
}

class _PlayerPageState extends State<PlayerPage> {
  VideoPlayerController? _controller;
  bool _saving = false;
  bool _ready = false;

  @override
  void initState() {
    super.initState();
    _init();
  }

  Future<void> _init() async {
    final c = VideoPlayerController.file(File(widget.videoPath));
    _controller = c;
    try {
      await c.initialize();
      await c.setLooping(true);
      await c.play();
      if (mounted) setState(() => _ready = true);
    } catch (_) {
      if (mounted) setState(() => _ready = false);
    }
  }

  @override
  void dispose() {
    _controller?.dispose();
    super.dispose();
  }

  Future<void> _saveToGallery() async {
    setState(() => _saving = true);
    try {
      final has = await Gal.hasAccess();
      if (!has) await Gal.requestAccess();
      await Gal.putVideo(widget.videoPath, album: 'AI Vlog');
      _snack('已保存到相册', ok: true);
    } catch (e) {
      _snack('保存失败：$e', ok: false);
    } finally {
      if (mounted) setState(() => _saving = false);
    }
  }

  void _snack(String msg, {required bool ok}) {
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(SnackBar(
      content: Text(msg),
      backgroundColor: ok ? Colors.green.shade600 : Colors.red.shade600,
      behavior: SnackBarBehavior.floating,
    ));
  }

  @override
  Widget build(BuildContext context) {
    final c = _controller;
    return Scaffold(
      backgroundColor: Colors.black,
      appBar: AppBar(
        backgroundColor: Colors.black,
        foregroundColor: Colors.white,
        title: Text(widget.title),
      ),
      body: Center(
        child: (_ready && c != null)
            ? AspectRatio(
                aspectRatio: c.value.aspectRatio == 0 ? 9 / 16 : c.value.aspectRatio,
                child: GestureDetector(
                  onTap: () => setState(() {
                    c.value.isPlaying ? c.pause() : c.play();
                  }),
                  child: Stack(
                    alignment: Alignment.center,
                    children: [
                      VideoPlayer(c),
                      if (!c.value.isPlaying)
                        const Icon(Icons.play_circle_fill, size: 72, color: Colors.white70),
                    ],
                  ),
                ),
              )
            : const CircularProgressIndicator(color: Colors.white),
      ),
      bottomNavigationBar: SafeArea(
        child: Padding(
          padding: const EdgeInsets.all(16),
          child: FilledButton.icon(
            onPressed: _saving ? null : _saveToGallery,
            icon: _saving
                ? const SizedBox(
                    width: 16, height: 16, child: CircularProgressIndicator(strokeWidth: 2))
                : const Icon(Icons.download),
            label: Text(_saving ? '保存中…' : '保存到相册'),
          ),
        ),
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

import '../models/frame.dart';
import '../providers/generation_provider.dart';
import 'player_page.dart';

/// 生成页：展示当天入选帧 → 一键生成 → 双阶段进度 → 完成跳播放器。
class GeneratePage extends ConsumerStatefulWidget {
  final String day;
  final List<Frame> frames;

  const GeneratePage({super.key, required this.day, required this.frames});

  @override
  ConsumerState<GeneratePage> createState() => _GeneratePageState();
}

class _GeneratePageState extends ConsumerState<GeneratePage> {
  @override
  void initState() {
    super.initState();
    // 进入页面时重置上一次生成状态
    WidgetsBinding.instance.addPostFrameCallback((_) {
      ref.read(generationProvider.notifier).reset();
    });
  }

  Future<void> _start() async {
    await ref.read(generationProvider.notifier).generate(widget.frames);
    final st = ref.read(generationProvider);
    if (st.stage == GenStage.done && st.videoPath != null && mounted) {
      Navigator.of(context).push(MaterialPageRoute(
        builder: (_) => PlayerPage(
          videoPath: st.videoPath!,
          title: st.script?.title ?? '我的 Vlog',
        ),
      ));
    }
  }

  @override
  Widget build(BuildContext context) {
    final st = ref.watch(generationProvider);

    return Scaffold(
      appBar: AppBar(title: Text('生成 Vlog · ${widget.day}')),
      body: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Text('本日入选 ${widget.frames.length} 个画面',
                style: const TextStyle(fontSize: 16, fontWeight: FontWeight.bold)),
            const SizedBox(height: 12),
            Expanded(
              child: st.isBusy || st.stage == GenStage.done || st.stage == GenStage.error
                  ? _statusView(st)
                  : _framePreview(),
            ),
            const SizedBox(height: 12),
            if (!st.isBusy)
              FilledButton.icon(
                onPressed: _start,
                icon: const Icon(Icons.auto_awesome),
                label: Text(st.stage == GenStage.done ? '重新生成' : '一键生成 Vlog'),
              ),
          ],
        ),
      ),
    );
  }

  Widget _framePreview() {
    return GridView.builder(
      gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(
        crossAxisCount: 3, crossAxisSpacing: 6, mainAxisSpacing: 6),
      itemCount: widget.frames.length,
      itemBuilder: (_, i) {
        final f = widget.frames[i];
        return _MiniThumb(text: f.sceneSummary, highlight: f.highlight);
      },
    );
  }

  Widget _statusView(GenerationState st) {
    IconData icon;
    Color color;
    switch (st.stage) {
      case GenStage.done:
        icon = Icons.check_circle;
        color = Colors.green;
        break;
      case GenStage.error:
        icon = Icons.error_outline;
        color = Colors.red;
        break;
      default:
        icon = Icons.movie_creation_outlined;
        color = Theme.of(context).colorScheme.primary;
    }

    return Center(
      child: Column(
        mainAxisAlignment: MainAxisAlignment.center,
        children: [
          Icon(icon, size: 64, color: color),
          const SizedBox(height: 16),
          Text(st.message.isEmpty ? '准备中…' : st.message,
              style: const TextStyle(fontSize: 16)),
          const SizedBox(height: 8),
          if (st.scriptSource == 'rule' && st.stage != GenStage.error)
            const Text('（未配置大模型，已用本地规则生成脚本）',
                style: TextStyle(fontSize: 12, color: Colors.orange)),
