/// 首页时间线：按天分组展示"AI 看到的世界"，每天可一键生成 Vlog。
class TimelinePage extends ConsumerWidget {
  const TimelinePage({super.key});

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final byDay = ref.watch(framesByDayProvider);

    return Scaffold(
      appBar: AppBar(
        title: const Text('时间线'),
        actions: [
          IconButton(
            icon: const Icon(Icons.refresh),
            onPressed: () => ref.invalidate(framesProvider),
          ),
        ],
      ),
      body: byDay.when(
        loading: () => const Center(child: CircularProgressIndicator()),
        error: (e, _) => Center(child: Text('加载失败：$e')),
        data: (map) {
          if (map.isEmpty) return _empty();
          final days = map.keys.toList();
          return ListView.builder(
            padding: const EdgeInsets.all(12),
            itemCount: days.length,
            itemBuilder: (_, i) {
              final day = days[i];
              final frames = map[day]!;
              return _DaySection(day: day, frames: frames);
            },
          );
        },
      ),
    );
  }

  Widget _empty() {
    return const Center(
      child: Column(
        mainAxisAlignment: MainAxisAlignment.center,
        children: [
          Icon(Icons.photo_library_outlined, size: 64, color: Colors.grey),
          SizedBox(height: 12),
          Text('还没有画面', style: TextStyle(color: Colors.grey)),
          SizedBox(height: 4),
          Text('连接设备同步，或放入示例数据', style: TextStyle(fontSize: 12, color: Colors.grey)),
        ],
      ),
    );
  }
