class _FrameCard extends StatelessWidget {
  final Frame frame;
  const _FrameCard({required this.frame});

  @override
  Widget build(BuildContext context) {
    final t = frame.capturedAt;
    final hh = t.hour.toString().padLeft(2, '0');
    final mm = t.minute.toString().padLeft(2, '0');
    return GestureDetector(
      onTap: () => _showDetail(context),
      child: SizedBox(
        width: 100,
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Stack(
              children: [
                FrameThumb(
                  path: frame.thumbPath,
                  width: 100,
                  height: 90,
                  radius: BorderRadius.circular(8),
                ),
                Positioned(
                  right: 4,
                  top: 4,
                  child: Container(
                    padding: const EdgeInsets.symmetric(horizontal: 5, vertical: 1),
                    decoration: BoxDecoration(
                      color: Colors.black54,
                      borderRadius: BorderRadius.circular(6),
                    ),
                    child: Text('${(frame.highlight * 100).round()}',
                        style: const TextStyle(color: Colors.white, fontSize: 10)),
                  ),
                ),
              ],
            ),
            const SizedBox(height: 2),
            Text('$hh:$mm', style: const TextStyle(fontSize: 10, color: Colors.grey)),
          ],
        ),
      ),
    );
  }

  void _showDetail(BuildContext context) {
    showModalBottomSheet(
      context: context,
      showDragHandle: true,
      builder: (_) => Padding(
        padding: const EdgeInsets.all(20),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            FrameThumb(
              path: frame.thumbPath,
              width: double.infinity,
              height: 200,
              radius: BorderRadius.circular(12),
            ),
            const SizedBox(height: 12),
            Text(frame.sceneSummary.isEmpty ? '（无场景描述）' : frame.sceneSummary,
                style: const TextStyle(fontSize: 16)),
            const SizedBox(height: 8),
            Wrap(
              spacing: 6,
              children: [
                Chip(label: Text('精彩度 ${(frame.highlight * 100).round()}')),
                if (frame.mood.isNotEmpty) Chip(label: Text('情绪 ${frame.mood}')),
                ...frame.tags.map((t) => Chip(label: Text('#$t'))),
              ],
            ),
          ],
        ),
      ),
    );
  }
}

