                        }
                    }
                } else {
                    resolveFallbackConfigurations(project)
                }
            }
        } else {
            // Variants are available, process them normally
            variants.all { variant ->
                resolveVariantConfigurations(project, variant)
            }
        }
    } else {
        resolveFallbackConfigurations(project)
    }
