import 'dart:convert';

import 'package:flutter_secure_storage/flutter_secure_storage.dart';
import 'package:shared_preferences/shared_preferences.dart';

import '../models/llm_config.dart';

/// 大模型配置持久化。
///
/// 优先用 flutter_secure_storage（安卓 Keystore 加密）。但部分机型（如 MIUI）
/// 的 encryptedSharedPreferences 有写入后读不回的已知问题，因此加 SharedPreferences
/// 兜底：写入时两处都写，读取时 secure 为空则回退 prefs，保证配置一定读得回来。
class ConfigStore {
  static const _kSecretApiKey = 'llm_api_key';
  static const _kNonSecret = 'llm_config_nonsecret';
  // prefs 兜底键
  static const _kPrefsApiKey = 'fallback_llm_api_key';
  static const _kPrefsNonSecret = 'fallback_llm_config_nonsecret';

  final FlutterSecureStorage _storage;

  ConfigStore({FlutterSecureStorage? storage})
      : _storage = storage ??
            const FlutterSecureStorage(
              aOptions: AndroidOptions(encryptedSharedPreferences: true),
            );

  /// 读取完整配置（含 apiKey）。未配置时返回默认空配置。
  Future<LlmConfig> load() async {
    String? nonSecretRaw;
    String apiKey = '';

    // 先试 secure_storage
    try {
      nonSecretRaw = await _storage.read(key: _kNonSecret);
      apiKey = await _storage.read(key: _kSecretApiKey) ?? '';
    } catch (_) {
      // secure_storage 读失败，忽略，走兜底
    }

    // secure 读不到就回退 prefs
    if (nonSecretRaw == null || nonSecretRaw.isEmpty || apiKey.isEmpty) {
      final prefs = await SharedPreferences.getInstance();
      nonSecretRaw ??= prefs.getString(_kPrefsNonSecret);
      if (nonSecretRaw == null || nonSecretRaw.isEmpty) {
        nonSecretRaw = prefs.getString(_kPrefsNonSecret);
      }
      if (apiKey.isEmpty) {
        apiKey = prefs.getString(_kPrefsApiKey) ?? '';
      }
    }

    if (nonSecretRaw == null || nonSecretRaw.isEmpty) {
      return LlmConfig(apiKey: apiKey);
    }
    try {
      final map = jsonDecode(nonSecretRaw) as Map<String, dynamic>;
      return LlmConfig.fromNonSecretJson(map, apiKey: apiKey);
    } catch (_) {
      return LlmConfig(apiKey: apiKey);
    }
  }

  /// 保存配置：secure_storage 与 SharedPreferences 双写。
  Future<void> save(LlmConfig config) async {
    final nonSecretJson = jsonEncode(config.toNonSecretJson());
    final key = config.apiKey.trim();

    // 1) secure_storage（尽力而为，失败不阻断）
    try {
      await _storage.write(key: _kNonSecret, value: nonSecretJson);
      if (key.isEmpty) {
        await _storage.delete(key: _kSecretApiKey);
      } else {
        await _storage.write(key: _kSecretApiKey, value: key);
      }
    } catch (_) {}

    // 2) SharedPreferences 兜底（保证读得回）
    final prefs = await SharedPreferences.getInstance();
    await prefs.setString(_kPrefsNonSecret, nonSecretJson);
    if (key.isEmpty) {
      await prefs.remove(_kPrefsApiKey);
    } else {
      await prefs.setString(_kPrefsApiKey, key);
    }
  }

  /// 清空配置（含 key）
  Future<void> clear() async {
    try {
      await _storage.delete(key: _kSecretApiKey);
      await _storage.delete(key: _kNonSecret);
    } catch (_) {}
    final prefs = await SharedPreferences.getInstance();
    await prefs.remove(_kPrefsApiKey);
    await prefs.remove(_kPrefsNonSecret);
  }
}

