import 'dart:convert';

import 'package:shared_preferences/shared_preferences.dart';

import '../models/frame.dart';

/// 帧编辑覆盖存储。
///
/// 设备/大模型给的标签、描述、情绪不总准确，允许用户修改。
/// 用户的修改按 image_id 存 SharedPreferences，加载帧时合并覆盖原值。
/// 只存被改过的字段，不动原始数据源。
class FrameEditStore {
  static const _kPrefix = 'frame_edit_';

  /// 保存某帧的编辑覆盖
  Future<void> saveEdit(
    String imageId, {
    String? sceneSummary,
    List<String>? tags,
    String? mood,
    double? highlight,
  }) async {
    final prefs = await SharedPreferences.getInstance();
    final map = <String, dynamic>{};
    if (sceneSummary != null) map['scene_summary'] = sceneSummary;
    if (tags != null) map['tags'] = tags;
    if (mood != null) map['mood'] = mood;
    if (highlight != null) map['highlight'] = highlight;
    await prefs.setString('$_kPrefix$imageId', jsonEncode(map));
  }

  /// 把编辑覆盖应用到一批帧上（加载时调用）
  Future<List<Frame>> applyEdits(List<Frame> frames) async {
    final prefs = await SharedPreferences.getInstance();
    return frames.map((f) {
      final raw = prefs.getString('$_kPrefix${f.imageId}');
      if (raw == null || raw.isEmpty) return f;
      try {
        final map = jsonDecode(raw) as Map<String, dynamic>;
        return f.copyWith(
          sceneSummary: map['scene_summary'] as String?,
          tags: (map['tags'] is List)
              ? (map['tags'] as List).map((e) => e.toString()).toList()
              : null,
          mood: map['mood'] as String?,
          highlight: (map['highlight'] is num) ? (map['highlight'] as num).toDouble() : null,
        );
      } catch (_) {
        return f;
      }
    }).toList();
  }

  /// 清除某帧的编辑（恢复原始）
  Future<void> clearEdit(String imageId) async {
    final prefs = await SharedPreferences.getInstance();
    await prefs.remove('$_kPrefix$imageId');
  }
}

final frameEditStore = FrameEditStore();

