/// 用 image 包缩放并重编码为 JPEG。失败返回 null（调用方回退原图）。
Uint8List? _compressJpeg(Uint8List src, {int maxSide = 512, int quality = 70}) {
  try {
    final decoded = img.decodeImage(src);
    if (decoded == null) return null;
    final longer = decoded.width > decoded.height ? decoded.width : decoded.height;
    final resized = longer > maxSide
        ? img.copyResize(
            decoded,
            width: decoded.width >= decoded.height ? maxSide : null,
            height: decoded.height > decoded.width ? maxSide : null,
          )
        : decoded;
    return Uint8List.fromList(img.encodeJpg(resized, quality: quality));
  } catch (_) {
    return null;
  }
}

