import 'player_page.dart';

/// Vlog 库：列出已接收/导入的成片，可播放、保存到相册、删除。
/// 顶部提供"导入视频"入口（手动选本地 mp4 入库，作为接收过渡；正式接收走"设备"页）。
class VlogLibraryPage extends StatefulWidget {
  const VlogLibraryPage({super.key});

  @override
  State<VlogLibraryPage> createState() => _VlogLibraryPageState();
}

class _VlogLibraryPageState extends State<VlogLibraryPage> {
  List<VlogRecord> _records = [];
  bool _loading = true;
  bool _importing = false;

  @override
  void initState() {
    super.initState();
    _load();
  }

  Future<void> _load() async {
    final list = await vlogStore.loadAll();
    if (!mounted) return;
    setState(() {
      _records = list;
      _loading = false;
    });
  }

  /// 导入本地视频：选文件 → 拷贝到应用目录 → 入库
  Future<void> _import() async {
    setState(() => _importing = true);
    try {
      final result = await FilePicker.platform.pickFiles(
        type: FileType.video,
        allowMultiple: false,
      );
      if (result == null || result.files.single.path == null) {
        setState(() => _importing = false);
        return;
      }
      final srcPath = result.files.single.path!;
      final srcName = result.files.single.name;

      // 拷贝到应用文档目录的 vlogs 下（避免原文件被清理后失效）
      final docs = await getApplicationDocumentsDirectory();
      final outDir = Directory(p.join(docs.path, 'vlogs'));
      if (!await outDir.exists()) await outDir.create(recursive: true);
      final destPath =
          p.join(outDir.path, 'import_${DateTime.now().millisecondsSinceEpoch}_$srcName');
      await File(srcPath).copy(destPath);

      final title = p.basenameWithoutExtension(srcName);
      await vlogStore.add(VlogRecord(
        videoPath: destPath,
        title: title,
        day: '',
        createdAt: DateTime.now().millisecondsSinceEpoch,
      ));
      await _load();
      _snack('已导入：$title', ok: true);
    } catch (e) {
      _snack('导入失败：$e', ok: false);
    } finally {
      if (mounted) setState(() => _importing = false);
    }
  }

  Future<void> _delete(VlogRecord r) async {
    await vlogStore.remove(r.videoPath);
    try {
      final f = File(r.videoPath);
      if (await f.exists()) await f.delete();
    } catch (_) {}
    _load();
  }

  void _snack(String msg, {required bool ok}) {
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(SnackBar(
      content: Text(msg),
      backgroundColor: ok ? Colors.green.shade600 : Colors.red.shade600,
      behavior: SnackBarBehavior.floating,
    ));
  }

  String _fmtTime(int ms) {
    final d = DateTime.fromMillisecondsSinceEpoch(ms);
    String two(int n) => n.toString().padLeft(2, '0');
    return '${d.year}-${two(d.month)}-${two(d.day)} ${two(d.hour)}:${two(d.minute)}';
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('Vlog 库'),
        actions: [
          IconButton(icon: const Icon(Icons.refresh), onPressed: _load),
        ],
      ),
      floatingActionButton: FloatingActionButton.extended(
        onPressed: _importing ? null : _import,
        icon: _importing
            ? const SizedBox(
                width: 18, height: 18, child: CircularProgressIndicator(strokeWidth: 2))
            : const Icon(Icons.file_upload_outlined),
        label: Text(_importing ? '导入中…' : '导入视频'),
      ),
      body: _loading
          ? const Center(child: CircularProgressIndicator())
          : _records.isEmpty
              ? _empty()
              : ListView.separated(
                  padding: const EdgeInsets.fromLTRB(12, 12, 12, 88),
                  itemCount: _records.length,
                  separatorBuilder: (_, _) => const SizedBox(height: 10),
                  itemBuilder: (_, i) => _tile(_records[i]),
                ),
    );
  }

  Widget _tile(VlogRecord r) {
    final exists = File(r.videoPath).existsSync();
    return Card(
      clipBehavior: Clip.antiAlias,
      child: ListTile(
        leading: Container(
          width: 48,
          height: 48,
          decoration: BoxDecoration(
            color: Theme.of(context).colorScheme.primaryContainer,
            borderRadius: BorderRadius.circular(8),
          ),
          child: const Icon(Icons.movie_outlined),
        ),
        title: Text(r.title, maxLines: 1, overflow: TextOverflow.ellipsis),
        subtitle: Text(
            '${_fmtTime(r.createdAt)}${exists ? "" : "（文件已删除）"}'),
        trailing: PopupMenuButton<String>(
          onSelected: (v) {
            if (v == 'delete') _delete(r);
          },
          itemBuilder: (_) => [
            const PopupMenuItem(value: 'delete', child: Text('删除')),
          ],
        ),
        onTap: exists
            ? () {
                Navigator.of(context).push(MaterialPageRoute(
                  builder: (_) => PlayerPage(videoPath: r.videoPath, title: r.title),
                ));
              }
            : null,
      ),
    );
  }

  Widget _empty() {
    return const Center(
      child: Column(
        mainAxisAlignment: MainAxisAlignment.center,
        children: [
          Icon(Icons.video_library_outlined, size: 64, color: Colors.grey),
          SizedBox(height: 12),
          Text('还没有 Vlog', style: TextStyle(color: Colors.grey)),
          SizedBox(height: 4),
          Text('连接设备接收，或点右下角导入本地视频',
              style: TextStyle(fontSize: 12, color: Colors.grey)),
        ],
      ),
    );
  }
}

import 'dart:async';

import 'package:flutter/material.dart';
import 'package:flutter_blue_plus/flutter_blue_plus.dart';
import 'package:permission_handler/permission_handler.dart';

/// 设备页：蓝牙扫描/连接设备。
///
/// 连接方式：手机开热点、设备连入同一局域网；蓝牙用于发现/连接与获取设备 IP，
/// 视频通过 WiFi/HTTP 按设备 IP 拉取（正式接收逻辑待硬件接口确定后接入）。
class DevicePage extends StatefulWidget {
  const DevicePage({super.key});

  @override
  State<DevicePage> createState() => _DevicePageState();
}

class _DevicePageState extends State<DevicePage> {
  final List<ScanResult> _results = [];
  bool _scanning = false;
  StreamSubscription<List<ScanResult>>? _scanSub;
  BluetoothDevice? _connected;

  @override
  void dispose() {
    _scanSub?.cancel();
    FlutterBluePlus.stopScan();
    super.dispose();
  }

  Future<bool> _ensurePermissions() async {
    // Android 12+ 需要蓝牙扫描/连接权限；定位权限部分机型扫描也需要
    final statuses = await [
      Permission.bluetoothScan,
      Permission.bluetoothConnect,
      Permission.locationWhenInUse,
    ].request();
    return statuses.values.every((s) => s.isGranted || s.isLimited);
  }

  Future<void> _startScan() async {
    final ok = await _ensurePermissions();
    if (!ok) {
      _snack('需要蓝牙权限才能扫描设备', ok: false);
      return;
    }
    if (!await FlutterBluePlus.isSupported) {
      _snack('此设备不支持蓝牙', ok: false);
      return;
    }
    // 确保蓝牙已开
    if (FlutterBluePlus.adapterStateNow != BluetoothAdapterState.on) {
      try {
        await FlutterBluePlus.turnOn();
      } catch (_) {}
    }

    setState(() {
      _results.clear();
      _scanning = true;
    });

    _scanSub?.cancel();
    _scanSub = FlutterBluePlus.scanResults.listen((results) {
      setState(() {
        _results
          ..clear()
          ..addAll(results.where((r) => r.device.platformName.isNotEmpty));
      });
    });

    try {
      await FlutterBluePlus.startScan(timeout: const Duration(seconds: 8));
    } catch (e) {
      _snack('扫描失败：$e', ok: false);
    }
    // 扫描结束后复位状态
    await Future.delayed(const Duration(seconds: 8));
    if (mounted) setState(() => _scanning = false);
  }

  Future<void> _connect(BluetoothDevice device) async {
    try {
      await FlutterBluePlus.stopScan();
      await device.connect(timeout: const Duration(seconds: 10));
      setState(() => _connected = device);
      _snack('已连接：${device.platformName}', ok: true);
      // TODO(接硬件接口): 连接后通过 BLE 特征值读取设备局域网 IP，
      //   再用 dio 走 HTTP 拉取 Vlog 列表/文件。等硬件端接口确定后接入。
    } catch (e) {
      _snack('连接失败：$e', ok: false);
    }
  }

  Future<void> _disconnect() async {
    try {
      await _connected?.disconnect();
    } catch (_) {}
    setState(() => _connected = null);
  }

  void _snack(String msg, {required bool ok}) {
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(SnackBar(
      content: Text(msg),
      backgroundColor: ok ? Colors.green.shade600 : Colors.red.shade600,
      behavior: SnackBarBehavior.floating,
    ));
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('设备'),
        actions: [
          if (_scanning)
            const Padding(
              padding: EdgeInsets.all(16),
              child: SizedBox(
                  width: 18, height: 18, child: CircularProgressIndicator(strokeWidth: 2)),
            )
          else
            IconButton(icon: const Icon(Icons.refresh), onPressed: _startScan),
        ],
      ),
      body: ListView(
        padding: const EdgeInsets.all(16),
        children: [
          if (_connected != null) _connectedCard(),
          _infoCard(),
          const SizedBox(height: 12),
          Row(
            children: [
              const Text('附近设备', style: TextStyle(fontWeight: FontWeight.bold)),
              const Spacer(),
              if (!_scanning)
                TextButton.icon(
                  onPressed: _startScan,
                  icon: const Icon(Icons.bluetooth_searching, size: 18),
                  label: const Text('扫描'),
                ),
            ],
          ),
          const SizedBox(height: 4),
          if (_results.isEmpty && !_scanning)
            const Padding(
              padding: EdgeInsets.symmetric(vertical: 24),
              child: Center(
                child: Text('点击"扫描"发现附近的蓝牙设备',
                    style: TextStyle(color: Colors.grey, fontSize: 13)),
              ),
            ),
          ..._results.map((r) => Card(
                child: ListTile(
                  leading: const Icon(Icons.bluetooth),
                  title: Text(r.device.platformName),
                  subtitle: Text(r.device.remoteId.str),
                  trailing: Text('${r.rssi} dBm',
                      style: const TextStyle(fontSize: 12, color: Colors.grey)),
                  onTap: () => _connect(r.device),
                ),
              )),
        ],
      ),
    );
  }

  Widget _connectedCard() {
    return Card(
      color: Theme.of(context).colorScheme.primaryContainer,
      child: ListTile(
        leading: const Icon(Icons.bluetooth_connected),
        title: Text('已连接：${_connected!.platformName}'),
        subtitle: const Text('（接收功能待硬件接口接入）'),
        trailing: TextButton(onPressed: _disconnect, child: const Text('断开')),
      ),
    );
  }

  Widget _infoCard() {
    return const Card(
      child: Padding(
        padding: EdgeInsets.all(16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text('如何接收 Vlog', style: TextStyle(fontWeight: FontWeight.bold)),
            SizedBox(height: 8),
            Text('1. 手机开热点，设备连入（同一局域网）', style: TextStyle(fontSize: 13)),
            Text('2. 蓝牙连接设备，获取其局域网地址', style: TextStyle(fontSize: 13)),
            Text('3. App 经 WiFi 从设备拉取生成好的 Vlog', style: TextStyle(fontSize: 13)),
            SizedBox(height: 6),
            Text('（当前可先在"Vlog 库"用"导入视频"手动添加）',
                style: TextStyle(fontSize: 12, color: Colors.grey)),
          ],
        ),
      ),
    );
  }
}

