Future<bool> _ensurePermissions() async {
  // Android 12+（含你的 Android 17）：只需蓝牙扫描/连接权限，不需要定位。
  final scan = await Permission.bluetoothScan.request();
  final connect = await Permission.bluetoothConnect.request();

  final granted = (scan.isGranted || scan.isLimited) &&
      (connect.isGranted || connect.isLimited);
  if (granted) return true;

  // 被永久拒绝：系统不再弹框，引导去设置手动开启
  if (scan.isPermanentlyDenied || connect.isPermanentlyDenied) {
    if (mounted) _showOpenSettingsDialog();
    return false;
  }
  return false;
}

void _showOpenSettingsDialog() {
  showDialog(
    context: context,
    builder: (_) => AlertDialog(
      title: const Text('需要蓝牙权限'),
      content: const Text('系统已拒绝蓝牙权限且不再弹出请求。请到「应用设置 → 权限」中，'
          '手动开启「附近的设备 / 蓝牙」权限，再回来扫描。'),
      actions: [
        TextButton(onPressed: () => Navigator.pop(context), child: const Text('取消')),
