import 'dart:io';

import 'package:dio/dio.dart';
import 'package:path/path.dart' as p;
import 'package:path_provider/path_provider.dart';

import 'vlog_store.dart';

/// 设备上的一个 Vlog 条目（来自 GET /list）
class RemoteVlog {
  final String name;
  final int size;

  const RemoteVlog({required this.name, required this.size});

  factory RemoteVlog.fromJson(Map<String, dynamic> j) => RemoteVlog(
        name: (j['name'] as String?) ?? '',
        size: (j['size'] as num?)?.toInt() ?? 0,
      );

  String get sizeText {
    if (size <= 0) return '';
    if (size < 1024 * 1024) return '${(size / 1024).toStringAsFixed(0)} KB';
    return '${(size / 1024 / 1024).toStringAsFixed(1)} MB';
  }
}

/// 下载进度回调（0.0~1.0，总长未知时可能为 null）
typedef DownloadProgress = void Function(double? progress);

/// 与开发板（局域网 HTTP 服务器）通信。
///
/// 约定接口：
/// - GET  {base}/list                     → JSON 数组 [{"name":"x.mp4","size":123}]
/// - GET  {base}/download?name=x.mp4       → mp4 文件流
class DeviceClient {
  final Dio _dio;

  DeviceClient({Dio? dio}) : _dio = dio ?? Dio();

  /// 把用户输入规整成 base url，如 "192.168.43.1" -> "http://192.168.43.1"
  static String normalizeBase(String input) {
    var s = input.trim();
    if (s.isEmpty) return '';
    if (!s.startsWith('http://') && !s.startsWith('https://')) {
      s = 'http://$s';
    }
    // 去掉结尾斜杠
    return s.replaceAll(RegExp(r'/+$'), '');
  }

  /// 拉取设备上的 Vlog 列表
  Future<List<RemoteVlog>> fetchList(String baseUrl) async {
    final base = normalizeBase(baseUrl);
    final resp = await _dio.get(
      '$base/list',
      options: Options(
        sendTimeout: const Duration(seconds: 8),
        receiveTimeout: const Duration(seconds: 8),
        responseType: ResponseType.json,
      ),
    );
    final data = resp.data;
    final list = <RemoteVlog>[];
    if (data is List) {
      for (final e in data) {
        if (e is Map) {
          final v = RemoteVlog.fromJson(Map<String, dynamic>.from(e));
          if (v.name.isNotEmpty) list.add(v);
        } else if (e is String && e.isNotEmpty) {
          // 兼容设备只返回文件名数组的情况
          list.add(RemoteVlog(name: e, size: 0));
        }
      }
    }
    return list;
  }

  /// 下载指定 Vlog 到应用目录，并写入本地库。返回本地文件路径。
  Future<String> download(
    String baseUrl,
    RemoteVlog vlog, {
    DownloadProgress? onProgress,
  }) async {
    final base = normalizeBase(baseUrl);
    final docs = await getApplicationDocumentsDirectory();
    final outDir = Directory(p.join(docs.path, 'vlogs'));
    if (!await outDir.exists()) await outDir.create(recursive: true);

    // 本地文件名加时间戳去重
    final safeName = vlog.name.replaceAll(RegExp(r'[^\w\.\-]'), '_');
    final destPath =
        p.join(outDir.path, 'dev_${DateTime.now().millisecondsSinceEpoch}_$safeName');

    await _dio.download(
      '$base/download',
      destPath,
      queryParameters: {'name': vlog.name},
      options: Options(
        receiveTimeout: const Duration(minutes: 5), // 视频可能较大
      ),
      onReceiveProgress: (received, total) {
        if (onProgress != null) {
          onProgress(total > 0 ? received / total : null);
        }
      },
    );

    // 入库
    final title = p.basenameWithoutExtension(vlog.name);
    await vlogStore.add(VlogRecord(
      videoPath: destPath,
      title: title,
      day: '',
      createdAt: DateTime.now().millisecondsSinceEpoch,
    ));
    return destPath;
  }

  /// 友好的错误描述
  static String describeError(Object e) {
    if (e is DioException) {
      switch (e.type) {
        case DioExceptionType.connectionTimeout:
        case DioExceptionType.sendTimeout:
        case DioExceptionType.receiveTimeout:
          return '连接超时：确认设备已连上手机热点、IP 填对了';
        case DioExceptionType.connectionError:
          return '连不上设备：检查 IP/端口，以及是否在同一网络';
        case DioExceptionType.badResponse:
          return '设备返回错误：HTTP ${e.response?.statusCode}';
        default:
          return '请求失败：${e.message ?? e.type.name}';
      }
    }
    return '出错：$e';
  }
}

final deviceClient = DeviceClient();

import 'package:flutter/material.dart';
import 'package:shared_preferences/shared_preferences.dart';

import '../services/device_client.dart';

/// 设备页：输入开发板局域网地址，拉取并下载其生成的 Vlog。
///
/// 连接方式：手机开热点、开发板连入 → 同一局域网。
/// App 按开发板 IP 走 HTTP：GET /list 拉列表，GET /download?name= 下载 mp4。
class DevicePage extends StatefulWidget {
  const DevicePage({super.key});

  @override
  State<DevicePage> createState() => _DevicePageState();
}

class _DevicePageState extends State<DevicePage> {
  static const _kLastIp = 'last_device_ip';

  final _ipCtrl = TextEditingController();
  bool _loading = false;
  List<RemoteVlog> _remote = [];
  String? _error;
  bool _connected = false;

  // 正在下载的项 -> 进度
  final Map<String, double?> _downloading = {};

  @override
  void initState() {
    super.initState();
    _restoreIp();
  }

  @override
  void dispose() {
    _ipCtrl.dispose();
    super.dispose();
  }

  Future<void> _restoreIp() async {
    final prefs = await SharedPreferences.getInstance();
    final last = prefs.getString(_kLastIp);
    if (last != null && last.isNotEmpty && mounted) {
      _ipCtrl.text = last;
    }
  }

  Future<void> _connect() async {
    final ip = _ipCtrl.text.trim();
    if (ip.isEmpty) {
      _snack('请输入设备地址', ok: false);
      return;
    }
    setState(() {
      _loading = true;
      _error = null;
    });
    try {
      final list = await deviceClient.fetchList(ip);
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString(_kLastIp, ip);
      if (!mounted) return;
      setState(() {
        _remote = list;
        _connected = true;
      });
      if (list.isEmpty) _snack('已连接，但设备上没有 Vlog', ok: true);
    } catch (e) {
      if (!mounted) return;
      setState(() {
        _error = DeviceClient.describeError(e);
        _connected = false;
      });
    } finally {
      if (mounted) setState(() => _loading = false);
    }
  }

  Future<void> _download(RemoteVlog v) async {
    setState(() => _downloading[v.name] = null);
    try {
      await deviceClient.download(
        _ipCtrl.text.trim(),
        v,
        onProgress: (prog) {
          if (mounted) setState(() => _downloading[v.name] = prog);
        },
      );
      if (!mounted) return;
      setState(() => _downloading.remove(v.name));
      _snack('已下载「${v.name}」，去「Vlog」查看', ok: true);
    } catch (e) {
      if (!mounted) return;
      setState(() => _downloading.remove(v.name));
      _snack(DeviceClient.describeError(e), ok: false);
    }
  }

  void _snack(String msg, {required bool ok}) {
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(SnackBar(
      content: Text(msg),
      backgroundColor: ok ? Colors.green.shade600 : Colors.red.shade600,
      behavior: SnackBarBehavior.floating,
    ));
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('设备')),
      body: ListView(
        padding: const EdgeInsets.all(16),
        children: [
          _connectCard(),
          const SizedBox(height: 12),
          if (_error != null)
            Card(
              color: Colors.red.shade50,
              child: Padding(
                padding: const EdgeInsets.all(12),
                child: Text(_error!, style: TextStyle(color: Colors.red.shade700, fontSize: 13)),
              ),
            ),
          if (_connected) ...[
            const SizedBox(height: 4),
            Row(
              children: [
                const Text('设备上的 Vlog', style: TextStyle(fontWeight: FontWeight.bold)),
                const Spacer(),
                Text('${_remote.length} 个', style: const TextStyle(color: Colors.grey, fontSize: 12)),
              ],
            ),
            const SizedBox(height: 6),
            if (_remote.isEmpty)
              const Padding(
                padding: EdgeInsets.symmetric(vertical: 16),
                child: Center(child: Text('设备上暂无 Vlog', style: TextStyle(color: Colors.grey))),
              ),
            ..._remote.map(_remoteTile),
          ],
        ],
      ),
    );
  }

  Widget _connectCard() {
    return Card(
      child: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            const Text('连接开发板', style: TextStyle(fontWeight: FontWeight.bold, fontSize: 16)),
            const SizedBox(height: 8),
            const Text('手机开热点、开发板连入后，输入开发板的局域网地址：',
                style: TextStyle(fontSize: 12, color: Colors.grey)),
            const SizedBox(height: 12),
            TextField(
              controller: _ipCtrl,
              keyboardType: TextInputType.url,
              decoration: const InputDecoration(
                labelText: '设备地址',
                hintText: '如 192.168.43.1 或 192.168.43.1:8080',
                border: OutlineInputBorder(),
                prefixIcon: Icon(Icons.router_outlined),
              ),
            ),
            const SizedBox(height: 12),
            SizedBox(
              width: double.infinity,
              child: FilledButton.icon(
                onPressed: _loading ? null : _connect,
                icon: _loading
                    ? const SizedBox(
                        width: 16, height: 16, child: CircularProgressIndicator(strokeWidth: 2))
                    : const Icon(Icons.link),
                label: Text(_loading ? '连接中…' : (_connected ? '刷新列表' : '连接')),
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _remoteTile(RemoteVlog v) {
    final downloading = _downloading.containsKey(v.name);
    final prog = _downloading[v.name];
    return Card(
      child: ListTile(
        leading: const Icon(Icons.movie_outlined),
        title: Text(v.name, maxLines: 1, overflow: TextOverflow.ellipsis),
        subtitle: downloading
            ? Row(
                children: [
                  Expanded(child: LinearProgressIndicator(value: prog)),
                  const SizedBox(width: 8),
                  Text(prog != null ? '${(prog * 100).round()}%' : '…',
                      style: const TextStyle(fontSize: 12)),
                ],
              )
            : Text(v.sizeText),
        trailing: downloading
            ? null
            : IconButton(
                icon: const Icon(Icons.download),
                onPressed: () => _download(v),
              ),
      ),
    );
  }
}

import 'dart:async';

import 'package:flutter_blue_plus/flutter_blue_plus.dart';
import 'package:permission_handler/permission_handler.dart';

/// 蓝牙客户端：发现开发板、连接、读取其局域网 IP。
///
/// ===== 与硬件端的 BLE 约定（硬件端需照此实现）=====
/// - 广播设备名以 "AIVLOG" 开头，如 "AIVLOG-01"
/// - Service UUID:      0000A100-0000-1000-8000-00805F9B34FB
/// - IP 特征值 UUID:    0000A101-0000-1000-8000-00805F9B34FB（可读 Read）
///   读取内容为 UTF-8 字符串 "ip:port"，如 "192.168.43.1:8080"
class BleClient {
  static final Guid serviceUuid = Guid('0000A100-0000-1000-8000-00805F9B34FB');
  static final Guid ipCharUuid = Guid('0000A101-0000-1000-8000-00805F9B34FB');

  /// 设备名识别前缀（不区分大小写）
  static const namePrefix = 'AIVLOG';

  /// 申请蓝牙权限。返回是否全部授予；permanentlyDenied 时抛 BlePermissionDenied。
  Future<bool> ensurePermissions() async {
    final scan = await Permission.bluetoothScan.request();
    final connect = await Permission.bluetoothConnect.request();
    final ok = (scan.isGranted || scan.isLimited) && (connect.isGranted || connect.isLimited);
    if (!ok && (scan.isPermanentlyDenied || connect.isPermanentlyDenied)) {
      throw BlePermissionDenied();
    }
    return ok;
  }

  /// 蓝牙是否可用/已开启，未开尝试打开
  Future<bool> ensureAdapterOn() async {
    if (!await FlutterBluePlus.isSupported) return false;
    if (FlutterBluePlus.adapterStateNow != BluetoothAdapterState.on) {
      try {
        await FlutterBluePlus.turnOn();
      } catch (_) {}
    }
    return FlutterBluePlus.adapterStateNow == BluetoothAdapterState.on;
  }

  /// 扫描设备，实时回调结果（只回名字含 AIVLOG 的，其余也返回但标记）。
  /// 调用方负责在合适时机 stopScan。
  Stream<List<ScanResult>> scan({Duration timeout = const Duration(seconds: 10)}) {
    FlutterBluePlus.startScan(timeout: timeout);
    return FlutterBluePlus.scanResults;
  }

  Future<void> stopScan() async {
    try {
      await FlutterBluePlus.stopScan();
    } catch (_) {}
  }

  /// 判断是否是自家开发板（按名字前缀）
  static bool isOurDevice(ScanResult r) {
    final name = r.device.platformName;
    return name.toUpperCase().startsWith(namePrefix);
  }

  /// 连接设备并读取其 IP:port。失败抛异常。
  Future<String> connectAndReadIp(BluetoothDevice device) async {
    await stopScan();
    await device.connect(timeout: const Duration(seconds: 12));
    try {
      final services = await device.discoverServices();
      BluetoothService? target;
      for (final s in services) {
        if (s.uuid == serviceUuid) {
          target = s;
          break;
        }
      }
      if (target == null) {
        throw BleException('设备未提供约定的服务（Service UUID 不匹配）');
      }
      BluetoothCharacteristic? ipChar;
      for (final c in target.characteristics) {
        if (c.uuid == ipCharUuid) {
          ipChar = c;
          break;
        }
      }
      if (ipChar == null) {
        throw BleException('设备未提供 IP 特征值');
      }
      final value = await ipChar.read();
      final ip = String.fromCharCodes(value).trim();
      if (ip.isEmpty) {
        throw BleException('读到的 IP 为空');
      }
      return ip;
    } finally {
      // 读到 IP 后可断开蓝牙，后续走 WiFi
      try {
        await device.disconnect();
      } catch (_) {}
    }
  }
}

class BlePermissionDenied implements Exception {}

class BleException implements Exception {
  final String message;
  BleException(this.message);
  @override
  String toString() => message;
}

final bleClient = BleClient();

